// Desktop appearance is unchanged by the phone layout (spec #28 A6, Linux
// Must Not Regress). The goldens under goldens/desktop/ are generated on the
// A6 base (the rebased A3, before any layout change) on the Linux platform
// and are never regenerated by A6: a difference here is a desktop change.
import 'package:anj_cloud/ui/admin_section.dart';
import 'package:anj_cloud/ui/app.dart';
import 'package:flutter/material.dart';
import 'package:flutter_test/flutter_test.dart';

import 'admin_section_test.dart' show FakeAdmin;
import 'layout_fixtures.dart';

final _linux = TargetPlatformVariant.only(TargetPlatform.linux);

Future<LayoutController> _pumpHome(WidgetTester tester, Size size) async {
  tester.view.physicalSize = size;
  tester.view.devicePixelRatio = 1;
  tester.platformDispatcher.accessibilityFeaturesTestValue =
      const FakeAccessibilityFeatures(disableAnimations: true);
  addTearDown(tester.view.reset);
  addTearDown(tester.platformDispatcher.clearAccessibilityFeaturesTestValue);
  final controller = layoutController();
  addTearDown(controller.dispose);
  await tester.pumpWidget(CloudApp(controller: controller));
  await tester.pumpAndSettle();
  return controller;
}

Future<void> _pumpAdmin(WidgetTester tester, AdminView view) async {
  tester.view.physicalSize = const Size(1400, 1000);
  tester.view.devicePixelRatio = 1;
  addTearDown(tester.view.reset);
  final api = FakeAdmin();
  await tester.pumpWidget(
    MaterialApp(
      debugShowCheckedModeBanner: false,
      home: AdminPage(call: api.call, onNotAdmin: () {}, initial: view),
    ),
  );
  await tester.pumpAndSettle();
}

Future<void> _golden(String name) => expectLater(
  find.byType(MaterialApp),
  matchesGoldenFile('goldens/desktop/$name.png'),
);

void main() {
  for (final width in [1280.0, 900.0, 640.0]) {
    testWidgets('home at $width', (tester) async {
      await _pumpHome(tester, Size(width, 720));
      await _golden('home-${width.toInt()}');
    }, variant: _linux);
  }

  testWidgets('conflict tab, row menu and select mode at 1280', (tester) async {
    await _pumpHome(tester, const Size(1280, 720));
    await tester.tap(find.widgetWithText(Tab, 'Conflict'));
    await tester.pumpAndSettle();
    await _golden('conflict-1280');
    await tester.tap(find.byTooltip('File actions').first);
    await tester.pumpAndSettle();
    await _golden('row-menu-1280');
    await tester.tapAt(const Offset(5, 5));
    await tester.pumpAndSettle();
    await tester.tap(find.widgetWithText(Tab, 'Home'));
    await tester.pumpAndSettle();
    await tester.tap(find.byKey(const ValueKey('select-button')));
    await tester.pumpAndSettle();
    await tester.tap(find.byKey(const ValueKey('select-card:Documents')));
    await tester.pumpAndSettle();
    await _golden('select-1280');
  }, variant: _linux);

  testWidgets('app menu and pairing dialog at 1280', (tester) async {
    await _pumpHome(tester, const Size(1280, 720));
    await tester.tap(find.byTooltip('AnJ Cloud menu'));
    await tester.pumpAndSettle();
    await _golden('app-menu-1280');
    await tester.tapAt(const Offset(5, 5));
    await tester.pumpAndSettle();
    await tester.tap(find.text('Device pairing'));
    await tester.pumpAndSettle();
    await _golden('pairing-1280');
  }, variant: _linux);

  testWidgets('delete everywhere confirmation at 1280', (tester) async {
    await _pumpHome(tester, const Size(1280, 720));
    // Photos: Documents, Music and Videos offer no Delete everywhere
    // (spec #34 P7).
    await tester.tap(
      find.descendant(
        of: find.byKey(const ValueKey('row:Photos')),
        matching: find.byTooltip('Folder actions'),
      ),
    );
    await tester.pumpAndSettle();
    await tester.tap(find.text('Delete everywhere'));
    await tester.pumpAndSettle();
    await _golden('delete-1280');
  }, variant: _linux);

  for (final view in AdminView.values) {
    testWidgets('admin ${view.name} at 1400', (tester) async {
      await _pumpAdmin(tester, view);
      await _golden('admin-${view.name}');
    }, variant: _linux);
  }

  testWidgets('admin user devices at 1400', (tester) async {
    await _pumpAdmin(tester, AdminView.users);
    await tester.tap(find.byKey(const ValueKey('admin-user-expand:alex')));
    await tester.pumpAndSettle();
    await _golden('admin-user-devices');
  }, variant: _linux);

  testWidgets('admin revoke confirmation at 1400', (tester) async {
    await _pumpAdmin(tester, AdminView.users);
    await tester.tap(find.byKey(const ValueKey('admin-user-expand:alex')));
    await tester.pumpAndSettle();
    await tester.tap(
      find.byKey(
        const ValueKey('admin-revoke:22222222-2222-4222-8222-222222222222'),
      ),
    );
    await tester.pumpAndSettle();
    await _golden('admin-revoke-confirm');
  }, variant: _linux);
}
